class Solution {
public:
    vector<string> allWords;
    string result;
    bool used[10];
    int val[26]; // char -> digit, -1 if unassigned
    bool isLead[26];
    int maxLen;

    bool isSolvable(vector<string>& words, string res) {
        result = res;
        allWords = words;
        allWords.push_back(result);

        for (int i = 0; i < 26; i++) { val[i] = -1; isLead[i] = false; }
        for (int i = 0; i < 10; i++) used[i] = false;

        maxLen = result.size();
        for (auto& w : words) {
            if ((int)w.size() > maxLen) return false; // sum can't exceed result length by more than 1
            if (w.size() >= 1) isLead[w[0]-'A'] = true;
        }
        isLead[result[0]-'A'] = true;

        return solve(0, 0);
    }

    // col: column index from right (0-based)
    // carry: carry into this column
    bool solve(int col, int carry) {
        if (col == maxLen) {
            return carry == 0;
        }
        return assign(col, 0, carry, 0);
    }

    // assign letters in column col
    // idx: which word we're processing (0..words count including result)
    // sumSoFar: sum of digits in this column from words (not including result subtraction)
    bool assign(int col, int idx, int carry, int sumSoFar) {
        int n = allWords.size();
        if (idx == n) {
            // last word is result
            // sumSoFar includes all words + result contribution
            // Actually handle: sum of words digits + carry - resultDigit*something
            // We'll compute differently below
            return false;
        }

        string& w = allWords[idx];
        int len = w.size();
        bool isResult = (idx == n-1);

        if (col >= len) {
            // no letter in this column for this word
            if (isResult) {
                // check column sum
                int total = sumSoFar + carry;
                if (total % 10 != 0) return false;
                return solve(col+1, total/10);
            }
            return assign(col, idx+1, carry, sumSoFar);
        }

        char c = w[len-1-col];
        int ci = c - 'A';

        if (val[ci] != -1) {
            int d = val[ci];
            if (isResult) {
                int total = sumSoFar + carry;
                if (total % 10 != d) return false;
                return solve(col+1, total/10);
            } else {
                return assign(col, idx+1, carry, sumSoFar + d);
            }
        }

        // try digits
        for (int d = 0; d <= 9; d++) {
            if (used[d]) continue;
            if (d == 0 && isLead[ci]) continue;

            used[d] = true;
            val[ci] = d;

            bool ok;
            if (isResult) {
                int total = sumSoFar + carry;
                if (total % 10 == d) {
                    ok = solve(col+1, total/10);
                } else {
                    ok = false;
                }
            } else {
                ok = assign(col, idx+1, carry, sumSoFar + d);
            }

            used[d] = false;
            val[ci] = -1;

            if (ok) return true;
        }

        return false;
    }
};
```

