class Solution {
public:
    string abbreviateProduct(int left, int right) {
        // count trailing zeros
        long long cnt2 = 0, cnt5 = 0;
        for (int i = left; i <= right; i++) {
            int x = i;
            while (x % 2 == 0) { x /= 2; cnt2++; }
            x = i;
            while (x % 5 == 0) { x /= 5; cnt5++; }
        }
        long long C = min(cnt2, cnt5);

        // total number of digits of product via log10
        long double logSum = 0;
        for (int i = left; i <= right; i++) logSum += log10l((long double)i);
        // number of digits of full product
        long long totalDigits = (long long)floorl(logSum) + 1;
        long long d = totalDigits - C; // digits after removing trailing zeros

        if (d <= 10) {
            // compute exact product using __int128 or unsigned long long carefully
            // product fits? after removing zeros, d<=10 digits means value < 10^10
            // compute full product removing trailing zeros as we go
            unsigned long long prod = 1;
            for (int i = left; i <= right; i++) {
                prod *= (unsigned long long)i;
                while (prod % 10 == 0) prod /= 10;
            }
            return to_string(prod) + "e" + to_string(C);
        }

        // need first 5 and last 5 digits
        // last 5 digits: multiply mod 10^... after removing factors 2^cnt2 and 5^cnt5 (min)
        // approach: multiply all, remove min(cnt2,cnt5) pairs of 2 and 5
        long long rem2 = C, rem5 = C;
        unsigned long long suffix = 1;
        const unsigned long long MOD = 100000000000ULL; // keep extra digits to be safe, use 10^11
        for (int i = left; i <= right; i++) {
            int x = i;
            while (x % 2 == 0 && rem2 > 0) { x /= 2; rem2--; }
            while (x % 5 == 0 && rem5 > 0) { x /= 5; rem5--; }
            suffix = (suffix * (unsigned long long)x) % MOD;
        }
        // last 5 digits
        unsigned long long last5 = suffix % 100000ULL;
        char lastbuf[16];
        sprintf(lastbuf, "%05llu", last5);
        string lastStr(lastbuf);

        // first 5 digits via fractional part of logSum
        long double frac = logSum - floorl(logSum);
