        long long first5 = (long long)lead;
        // guard
        if (first5 >= 100000) first5 = 99999;
        if (first5 < 10000) first5 = 10000;
        string firstStr = to_string(first5);

        return firstStr + "..." + lastStr + "e" + to_string(C);
    }
