class Solution {
public:
    int numFactoredBinaryTrees(vector<int>& arr) {
        const int MOD = 1e9 + 7;
        sort(arr.begin(), arr.end());
        int n = arr.size();
        unordered_map<long long, int> idx;
        for (int i = 0; i < n; i++) idx[arr[i]] = i;
        vector<long long> dp(n, 1);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    long long other = arr[i] / arr[j];
                    auto it = idx.find(other);
                    if (it != idx.end()) {
                        dp[i] = (dp[i] + dp[j] * dp[it->second]) % MOD;
                    }
                }
            }
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) ans = (ans + dp[i]) % MOD;
        return (int)ans;
    }
};
