class Solution {
public:
    vector<int> parent, sz;
    int find(int x){ while(parent[x]!=x){ parent[x]=parent[parent[x]]; x=parent[x]; } return x; }
    void uni(int a, int b){
        a=find(a); b=find(b);
        if(a==b) return;
        if(sz[a]<sz[b]) swap(a,b);
        parent[b]=a; sz[a]+=sz[b];
    }
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m=grid.size(), n=grid[0].size();
        int top = m*n; // virtual node
        parent.resize(m*n+1); sz.assign(m*n+1,1);
        for(int i=0;i<=m*n;i++) parent[i]=i;

        vector<vector<int>> g = grid;
        for(auto& h: hits) g[h[0]][h[1]] = 0;

        auto id=[&](int r,int c){ return r*n+c; };
        int dr[4]={-1,1,0,0}, dc[4]={0,0,-1,1};

        // build union find on remaining grid
        for(int r=0;r<m;r++) for(int c=0;c<n;c++){
            if(g[r][c]==1){
                if(r==0) uni(id(r,c), top);
                for(int d=0;d<4;d++){
                    int nr=r+dr[d], nc=c+dc[d];
                    if(nr>=0&&nr<m&&nc>=0&&nc<n&&g[nr][nc]==1)
                        uni(id(r,c), id(nr,nc));
                }
            }
        }

        int k=hits.size();
        vector<int> result(k,0);
        for(int i=k-1;i>=0;i--){
            int r=hits[i][0], c=hits[i][1];
            if(grid[r][c]==0) continue; // no brick there originally
            int before = sz[find(top)];
            g[r][c]=1;
            if(r==0) uni(id(r,c), top);
            for(int d=0;d<4;d++){
                int nr=r+dr[d], nc=c+dc[d];
                if(nr>=0&&nr<m&&nc>=0&&nc<n&&g[nr][nc]==1)
                    uni(id(r,c), id(nr,nc));
            }
            int after = sz[find(top)];
            int diff = after - before - 1;
            result[i] = max(0, diff);
        }
        return result;
    }
};
