#include <set>
#include <queue>
using namespace std;

class MKAverage {
public:
    int m, k;
    queue<int> q;
    multiset<int> low, mid, high;
    long long midSum = 0;

    MKAverage(int m, int k) {
        this->m = m;
        this->k = k;
    }

    void rebalance() {
        // ensure low has exactly k, high has exactly k, mid has m-2k
        // fix low size
        while ((int)low.size() > k) {
            int v = *low.rbegin();
            low.erase(prev(low.end()));
            mid.insert(v);
            midSum += v;
        }
        while ((int)low.size() < k && !mid.empty()) {
            int v = *mid.begin();
            mid.erase(mid.begin());
            midSum -= v;
            low.insert(v);
        }
        while ((int)high.size() > k) {
            int v = *high.begin();
            high.erase(high.begin());
            mid.insert(v);
            midSum += v;
        }
        while ((int)high.size() < k && !mid.empty()) {
            int v = *mid.rbegin();
            mid.erase(prev(mid.end()));
            midSum -= v;
            high.insert(v);
        }
    }

    void addToStructures(int num) {
        // insert into appropriate set
        if (!low.empty() && num <= *low.rbegin()) {
            low.insert(num);
        } else if (!high.empty() && num >= *high.begin()) {
            high.insert(num);
        } else {
            mid.insert(num);
            midSum += num;
        }
        rebalance();
    }

    void removeFromStructures(int num) {
        auto it = low.find(num);
        if (it != low.end()) {
            low.erase(it);
        } else {
            it = high.find(num);
            if (it != high.end()) {
                high.erase(it);
            } else {
                it = mid.find(num);
                mid.erase(it);
                midSum -= num;
            }
        }
        rebalance();
    }

    void addElement(int num) {
        q.push(num);
        addToStructures(num);
        if ((int)q.size() > m) {
            int old = q.front();
            q.pop();
            removeFromStructures(old);
        }
    }

    int calculateMKAverage() {
        if ((int)q.size() < m) return -1;
        int cnt = m - 2 * k;
        return (int)(midSum / cnt);
    }
};
```

