class Solution {
public:
    bool canCross(vector<int>& stones) {
        int n = stones.size();
        unordered_map<int,int> pos;
        for (int i = 0; i < n; i++) pos[stones[i]] = i;
        vector<unordered_set<int>> dp(n);
        dp[0].insert(0);
        for (int i = 0; i < n; i++) {
            for (int k : dp[i]) {
                for (int step = k-1; step <= k+1; step++) {
                    if (step <= 0) continue;
                    int next = stones[i] + step;
                    if (pos.count(next)) {
                        int j = pos[next];
                        if (j == n-1) return true;
                        dp[j].insert(step);
                    }
                }
            }
        }
        return n == 1;
    }
};
