class Solution {
public:
    int maxScore(vector<int>& nums) {
        int m = nums.size();
        vector<int> dp(1 << m, 0);
        for (int mask = 0; mask < (1 << m); mask++) {
            int cnt = __builtin_popcount(mask);
            if (cnt % 2 != 0) continue;
            int op = cnt / 2 + 1;
            for (int i = 0; i < m; i++) {
                if (mask & (1 << i)) continue;
                for (int j = i + 1; j < m; j++) {
                    if (mask & (1 << j)) continue;
                    int nmask = mask | (1 << i) | (1 << j);
                    dp[nmask] = max(dp[nmask], dp[mask] + op * __gcd(nums[i], nums[j]));
                }
            }
        }
        return dp[(1 << m) - 1];
    }
};
