class Solution {
public:
    int maximumANDSum(vector<int>& nums, int numSlots) {
        int n = nums.size();
        vector<int> pow3(numSlots+1);
        pow3[0]=1;
        for(int i=1;i<=numSlots;i++) pow3[i]=pow3[i-1]*3;
        int total = pow3[numSlots];
        vector<int> dp(total, -1);
        dp[0]=0;
        int ans=0;
        for(int mask=0;mask<total;mask++){
            if(dp[mask]<0) continue;
            // count placed numbers
            int placed=0, m=mask;
            for(int s=0;s<numSlots;s++){ placed += m%3; m/=3; }
            if(placed>=n) { ans=max(ans,dp[mask]); continue; }
            int num = nums[placed];
            m=mask;
            for(int s=0;s<numSlots;s++){
                int used = (mask/pow3[s])%3;
                if(used<2){
                    int nmask = mask + pow3[s];
                    int val = dp[mask] + (num & (s+1));
                    if(val>dp[nmask]) dp[nmask]=val;
                }
            }
            ans=max(ans,dp[mask]);
        }
        return ans;
    }
};
