class Solution {
public:
    string maximumBinaryString(string binary) {
        int n = binary.size();
        int firstZero = -1;
        int zeros = 0;
        for (int i = 0; i < n; i++) {
            if (binary[i] == '0') {
                if (firstZero == -1) firstZero = i;
                zeros++;
