class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size(), n = seats[0].size();
        vector<int> valid(m, 0);
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (seats[i][j] == '.') valid[i] |= (1 << j);

        int full = (1 << n);
        vector<vector<int>> dp(m, vector<int>(full, -1));
        int ans = 0;

        for (int i = 0; i < m; i++) {
            for (int mask = 0; mask < full; mask++) {
                // mask must be subset of valid[i]
                if ((mask & valid[i]) != mask) continue;
                // no two adjacent in same row
                if (mask & (mask << 1)) continue;

                int best = -1;
                if (i == 0) {
                    best = __builtin_popcount(mask);
                } else {
                    for (int prev = 0; prev < full; prev++) {
                        if (dp[i-1][prev] < 0) continue;
                        // check upper-left and upper-right conflicts
                        if (mask & (prev << 1)) continue;
                        if (mask & (prev >> 1)) continue;
                        best = max(best, dp[i-1][prev] + __builtin_popcount(mask));
                    }
                }
                dp[i][mask] = best;
                if (best > ans) ans = best;
            }
        }
        return ans;
    }
};
