class Solution {
public:
    int maxSumTwoNoOverlap(vector<int>& nums, int firstLen, int secondLen) {
        int n = nums.size();
        vector<int> pre(n+1, 0);
        for (int i = 0; i < n; i++) pre[i+1] = pre[i] + nums[i];

        auto solve = [&](int L1, int L2) {
            int best = 0, maxL1 = 0;
            // L1 before L2
            for (int j = L1 + L2; j <= n; j++) {
                // L1 window ends at j-L2, i.e. [j-L2-L1, j-L2)
                maxL1 = max(maxL1, pre[j-L2] - pre[j-L2-L1]);
                int sumL2 = pre[j] - pre[j-L2];
                best = max(best, maxL1 + sumL2);
            }
            return best;
        };

        return max(solve(firstLen, secondLen), solve(secondLen, firstLen));
    }
};
