- Sort flowers. Cap each at target for beauty purposes.
- We decide how many gardens to make complete (from the largest ones, cheapest to complete). Then remaining gardens are incomplete, maximize their minimum with the leftover flowers.

Let me iterate over the number of complete gardens `c` (making the largest `c` gardens complete). For the rest, binary search / two-pointer the max achievable minimum.

```cpp
class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        int n = flowers.size();
        sort(flowers.begin(), flowers.end());
        vector<long long> f(n);
        for (int i = 0; i < n; i++) f[i] = min((long long)flowers[i], (long long)target);

        // prefix sums
        vector<long long> pre(n+1, 0);
        for (int i = 0; i < n; i++) pre[i+1] = pre[i] + f[i];

        // cost to complete the largest c gardens (indices n-c..n-1)
        // suffix cost of making garden j complete = target - f[j]
        // costComplete[c] = sum over last c gardens of (target - f[j])
        // Since sorted, largest values are cheapest to complete.

        long long ans = 0;

        // For a given number of complete gardens c (0..n), the first n-c gardens are incomplete.
        // We need to maximize min of first n-c gardens with remaining budget.
        // Precompute suffix cost to complete.
        vector<long long> suffCost(n+1, 0); // suffCost[i] = cost to complete gardens i..n-1
        for (int i = n-1; i >= 0; i--) suffCost[i] = suffCost[i+1] + (target - f[i]);

        // helper: for first m gardens (m = n-c), given budget, max achievable minimum (capped at target-1)
        // f is sorted ascending. We use two-pointer over c.

        for (int c = 0; c <= n; c++) {
            int m = n - c; // incomplete gardens are 0..m-1
            long long budget = newFlowers - suffCost[m]; // cost to complete last c
            if (budget < 0) break; // increasing c only increases cost, so break

            long long incompleteBeauty = 0;
            if (m > 0) {
                // maximize minimum of first m gardens, each < target (max target-1)
                // find largest x in [0, target-1] such that cost to raise all first m to x <= budget
                // cost = x*k - pre[k] where k = number of gardens with f < x among first m
                // binary search on x
                long long lo = f[0], hi = target - 1;
                // if f[0] already >= target-1... all incomplete are already at their capped values; min could be f[0]
                if (lo > hi) {
                    // all first m gardens have f value = target (impossible since incomplete)
                    incompleteBeauty = 0; // shouldn't happen for incomplete
                } else {
                    long long best = 0;
                    while (lo <= hi) {
                        long long x = (lo + hi) / 2;
                        // count in first m with f < x -> upper_bound
                        int k = upper_bound(f.begin(), f.begin()+m, x-1) - f.begin();
                        // actually gardens with value < x
                        // k = number with f[i] < x
                        long long cost = x * k - pre[k];
                        if (cost <= budget) {
                            best = x;
                            lo = x + 1;
                        } else {
                            hi = x - 1;
                        }
                    }
                    incompleteBeauty = best * (long long)partial;
                }
            }

            long long totalBeauty = (long long)c * full + incompleteBeauty;
            ans = max(ans, totalBeauty);
        }

        return ans;
    }
};
```

The binary search inside the loop over `c` makes it O(n log(target) log n). With n up to 1e5, that's about 1e5 * 17 * 17 ≈ 3e7,

