class Solution {
public:
    int minMalwareSpread(vector<vector<int>>& graph, vector<int>& initial) {
        int n = graph.size();
        sort(initial.begin(), initial.end());
        int bestNode = initial[0];
        int bestCount = INT_MAX;
        for (int removed : initial) {
            vector<int> infected(n, 0);
            queue<int> q;
            for (int src : initial) {
                if (src == removed) continue;
                if (!infected[src]) { infected[src] = 1; q.push(src); }
            }
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v = 0; v < n; v++) {
                    if (v == removed) continue;
                    if (graph[u][v] && !infected[v]) {
                        infected[v] = 1;
                        q.push(v);
                    }
                }
            }
            int cnt = 0;
            for (int i = 0; i < n; i++) cnt += infected[i];
            if (cnt < bestCount) {
                bestCount = cnt;
                bestNode = removed;
            }
        }
        return bestNode;
    }
};
```

