class Solution {
public:
    int minDays(vector<int>& bloomDay, int m, int k) {
        long long n = bloomDay.size();
        if ((long long)m * k > n) return -1;
        int lo = 1, hi = 0;
        for (int d : bloomDay) hi = max(hi, d);
        auto can = [&](int day) {
            int bouquets = 0, adj = 0;
            for (int d : bloomDay) {
                if (d <= day) {
                    adj++;
                    if (adj == k) { bouquets++; adj = 0; }
                } else adj = 0;
            }
            return bouquets >= m;
        };
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (can(mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};
