class Solution {
public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        int n = tasks.size();
        int full = (1 << n) - 1;
        // precompute whether a subset fits in one session
        vector<bool> fits(1 << n, false);
        for (int mask = 0; mask <= full; mask++) {
            int sum = 0;
            for (int i = 0; i < n; i++)
                if (mask & (1 << i)) sum += tasks[i];
            fits[mask] = (sum <= sessionTime);
        }
        vector<int> dp(1 << n, INT_MAX);
        dp[0] = 0;
        for (int mask = 1; mask <= full; mask++) {
            // enumerate submasks
            for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                if (fits[sub] && dp[mask ^ sub] != INT_MAX) {
                    dp[mask] = min(dp[mask], dp[mask ^ sub] + 1);
                }
            }
        }
        return dp[full];
    }
};
