        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask] == -1) continue;
            for (int j = 0; j < n; j++) {
                if (mask & (1 << j)) continue;
                if (dp[mask] + nums[j] <= target) {
                    int next = mask | (1 << j);
                    if (dp[next] == -1)
                        dp[next] = (dp[mask] + nums[j]) % target;
                }
            }
        }
        return dp[(1 << n) - 1] == 0;
    }
};
