public:
    int solve(vector<int>& s, int k) {
        int m = s.size();
        // dp[i][j] = max sum using first i elements, picking j, non-adjacent
        vector<vector<int>> dp(m + 1, vector<int>(k + 1, 0));
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= k; j++) {
                int notTake = dp[i-1][j];
                int take = (i >= 2 ? dp[i-2][j-1] : 0) + s[i-1];
                dp[i][j] = max(notTake, take);
