            bool res;
            if (j+1 < m && p[j+1] == '*') {
                res = solve(i, j+2) || (firstMatch && solve(i+1, j));
            } else {
                res = firstMatch && solve(i+1, j+1);
            }
            dp[i][j] = res;
            return res;
        };
        return solve(0, 0);
    }
};
