    vector<int> restoreArray(vector<vector<int>>& adjacentPairs) {
        unordered_map<int, vector<int>> adj;
        for (auto& p : adjacentPairs) {
            adj[p[0]].push_back(p[1]);
            adj[p[1]].push_back(p[0]);
        }
        int start = 0;
        for (auto& kv : adj) {
            if (kv.second.size() == 1) {
                start = kv.first;
                break;
            }
        }
        int n = adjacentPairs.size() + 1;
        vector<int> res;
        res.reserve(n);
        int prev = start - 1; // sentinel unlikely, but handle properly
        int cur = start;
        res.push_back(cur);
        bool first = true;
        int last = 0;
        for (int i = 1; i < n; i++) {
            auto& nbrs = adj[cur];
            int next;
            if (first) {
                next = nbrs[0];
                first = false;
            } else {
                next = (nbrs[0] == last) ? nbrs[1] : nbrs[0];
