        if (s1 == s2) return true;
        if (s1.size() != s2.size()) return false;

        string key = s1 + "#" + s2;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;

        int cnt[26] = {0};
        for (int i = 0; i < s1.size(); i++) {
            cnt[s1[i]-'a']++;
            cnt[s2[i]-'a']--;
