    vector<double> medianSlidingWindow(vector<int>& nums, int k) {
        multiset<int> window(nums.begin(), nums.begin() + k);
        auto mid = next(window.begin(), (k - 1) / 2);
        vector<double> result;
        int n = nums.size();
        for (int i = k; ; i++) {
            double median = ((double)*mid + *next(mid, (k + 1) % 2 == 0 ? 0 : 1)) / 2.0;
