class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int n = target.size();
        vector<int> dp(1 << n, INT_MAX);
        dp[0] = 0;

        vector<vector<int>> counts(stickers.size(), vector<int>(26, 0));
        for (int i = 0; i < stickers.size(); i++)
            for (char c : stickers[i]) counts[i][c - 'a']++;

        for (int state = 0; state < (1 << n); state++) {
            if (dp[state] == INT_MAX) continue;
            for (auto& cnt : counts) {
                vector<int> c = cnt;
                int newState = state;
                for (int i = 0; i < n; i++) {
                    if (!(state & (1 << i))) {
                        int ch = target[i] - 'a';
                        if (c[ch] > 0) {
                            c[ch]--;
                            newState |= (1 << i);
                        }
                    }
                }
                if (dp[state] + 1 < dp[newState])
                    dp[newState] = dp[state] + 1;
            }
        }

        return dp[(1 << n) - 1] == INT_MAX ? -1 : dp[(1 << n) - 1];
    }
};
