class StreamChecker {
public:
    struct Node {
        int ch[26];
        bool end;
        Node() { memset(ch, -1, sizeof(ch)); end = false; }
    };
    vector<Node> trie;
    string stream;
    int maxLen = 0;

    StreamChecker(vector<string>& words) {
        trie.push_back(Node());
        for (auto& w : words) {
            maxLen = max(maxLen, (int)w.size());
            int cur = 0;
            for (int i = w.size() - 1; i >= 0; i--) {
                int c = w[i] - 'a';
                if (trie[cur].ch[c] == -1) {
                    trie[cur].ch[c] = trie.size();
                    trie.push_back(Node());
                }
                cur = trie[cur].ch[c];
            }
            trie[cur].end = true;
        }
    }

    bool query(char letter) {
        stream.push_back(letter);
        int cur = 0;
        int n = stream.size();
        for (int i = n - 1; i >= 0 && n - i <= maxLen; i--) {
            int c = stream[i] - 'a';
            if (trie[cur].ch[c] == -1) return false;
            cur = trie[cur].ch[c];
            if (trie[cur].end) return true;
        }
        return false;
    }
};
