class Solution {
public:
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        int coprime[51][51];
        for (int i = 1; i <= 50; i++)
            for (int j = 1; j <= 50; j++)
                coprime[i][j] = (__gcd(i, j) == 1);

        vector<int> ans(n, -1);
        // for each value 1..50, store stack of (node, depth)
        vector<pair<int,int>> lastNode(51, {-1, -1}); // node, depth

        // iterative DFS
        vector<int> stackNode, stackParent, stackState, stackDepth;
        // save/restore mechanism: store previous value of lastNode when entering
        vector<pair<int,pair<int,int>>> saved; // for undo: value, (prevNode, prevDepth)

        stackNode.push_back(0);
        stackParent.push_back(-1);
        stackState.push_back(0);
        stackDepth.push_back(0);

        while (!stackNode.empty()) {
            int node = stackNode.back();
            int parent = stackParent.back();
            int state = stackState.back();
            int depth = stackDepth.back();

            if (state == 0) {
                stackState.back() = 1;
                int val = nums[node];
                // find closest ancestor
                int best = -1, bestDepth = -1;
                for (int v = 1; v <= 50; v++) {
                    if (coprime[val][v] && lastNode[v].first != -1) {
                        if (lastNode[v].second > bestDepth) {
                            bestDepth = lastNode[v].second;
                            best = lastNode[v].first;
                        }
                    }
                }
                ans[node] = best;
                // save and update
                saved.push_back({val, lastNode[val]});
                lastNode[val] = {node, depth};
                // push children
                for (int nb : adj[node]) {
                    if (nb != parent) {
                        stackNode.push_back(nb);
                        stackParent.push_back(node);
                        stackState.push_back(0);
                        stackDepth.push_back(depth + 1);
                    }
                }
            } else {
                // restore
                int val = nums[node];
                lastNode[val] = saved.back().second;
                saved.pop_back();
                stackNode.pop_back();
                stackParent.pop_back();
                stackState.pop_back();
                stackDepth.pop_back();
            }
        }
        return ans;
    }
};
