        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }
        if (root == -1) return false;

        vector<bool> visited(n, false);
        stack<int> st;
        st.push(root);
        int count = 0;
        while (!st.empty()) {
            int node = st.top(); st.pop();
            if (visited[node]) return false;
            visited[node] = true;
            count++;
            if (leftChild[node] != -1) st.push(leftChild[node]);
            if (rightChild[node] != -1) st.push(rightChild[node]);
        }
        return count == n;
    }
};
